// `en` uses literal string types (via `as const`) for editor autocomplete
// on this file; other dictionaries just need matching structure with
// arbitrary string values, so widen every leaf to `string` here.
type Widen<T> = T extends string ? string : { [K in keyof T]: Widen<T[K]> };
export type UiDictionary = Widen<typeof en>;
